class Solution {
public:
    int kthLargestValue(vector<vector<int>>& matrix, int k) {
        int m = matrix.size();
        int n = matrix[0].size();

        vector<int> values;
        values.reserve(m * n);

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = matrix[i][j];
                if (i > 0) val ^= matrix[i - 1][j];
                if (j > 0) val ^= matrix[i][j - 1];
                if (i > 0 && j > 0) val ^= matrix[i - 1][j - 1];
                matrix[i][j] = val;
                values.push_back(val);
            }
        }

        nth_element(values.begin(), values.begin() + (k - 1), values.end(), greater<int>());
        return values[k - 1];
    }
};
